package com.mustafafaraz.locateme

import android.os.Bundle
import android.view.View
import android.widget.*
import androidx.appcompat.app.AppCompatActivity

class EditItem : AppCompatActivity() {

    private lateinit var backButton: ImageView
    private lateinit var itemTypeSpinner: Spinner
    private lateinit var itemTitle: EditText
    private lateinit var itemCategory: Spinner
    private lateinit var itemDescription: EditText
    private lateinit var itemStatusSpinner: Spinner
    private lateinit var itemLocation: EditText
    private lateinit var locationLabel: TextView
    private lateinit var saveButton: Button
    private lateinit var deleteButton: Button

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_edit_item)

        initializeViews()
        setupSpinners()
        loadStaticData()
        setupClickListeners()
    }

    private fun initializeViews() {
        backButton = findViewById(R.id.back_button)
        itemTypeSpinner = findViewById(R.id.item_type_spinner)
        itemTitle = findViewById(R.id.item_title)
        itemCategory = findViewById(R.id.item_category)
        itemDescription = findViewById(R.id.item_description)
        itemStatusSpinner = findViewById(R.id.item_status_spinner)
        itemLocation = findViewById(R.id.item_location)
        locationLabel = findViewById(R.id.location_label)
        saveButton = findViewById(R.id.save_button)
        deleteButton = findViewById(R.id.delete_button)
    }

    private fun setupSpinners() {
        // Item Type Spinner
        val itemTypes = arrayOf("Lost Item", "Found Item")
        val typeAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, itemTypes)
        typeAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemTypeSpinner.adapter = typeAdapter

        // Update location label when item type changes
        itemTypeSpinner.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onItemSelected(parent: AdapterView<*>?, view: View?, position: Int, id: Long) {
                updateLocationLabel(position)
            }

            override fun onNothingSelected(parent: AdapterView<*>?) {}
        }

        // Category Spinner
        val categories = arrayOf(
            "Select Category",
            "ELECTRONICS",
            "BAGS",
            "KEYS",
            "CLOTHING",
            "OTHER"
        )
        val categoryAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, categories)
        categoryAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemCategory.adapter = categoryAdapter

        // Status Spinner
        val statuses = arrayOf("active", "resolved", "expired")
        val statusAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, statuses)
        statusAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemStatusSpinner.adapter = statusAdapter
    }

    private fun loadStaticData() {
        // Load static/hardcoded data
        itemTitle.setText("Dark Chocolate Cake")
        itemDescription.setText("Lost my chocolate cake in the library. It was in a blue container with my name on it. Please contact me if you find it.")
        itemLocation.setText("Library - 3rd floor")

        // Set default selections
        itemTypeSpinner.setSelection(0) // Lost Item
        itemCategory.setSelection(5) // OTHER (valid index)
        itemStatusSpinner.setSelection(0) // active
    }

    private fun setupClickListeners() {
        backButton.setOnClickListener {
            finish()
        }

        saveButton.setOnClickListener {
            Toast.makeText(this, "Item updated successfully", Toast.LENGTH_SHORT).show()
            finish()
        }

        deleteButton.setOnClickListener {
            Toast.makeText(this, "Item deleted", Toast.LENGTH_SHORT).show()
            finish()
        }
    }

    private fun updateLocationLabel(typePosition: Int) {
        locationLabel.text = if (typePosition == 0) {
            "Where did you lose it? *"
        } else {
            "Where did you find it? *"
        }
    }
}

package com.mustafafaraz.locateme

import android.app.AlertDialog
import android.net.Uri
import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.*
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.mustafafaraz.locateme.adapter.EditPhotoAdapter
import com.mustafafaraz.locateme.data.api.RetrofitClient
import com.mustafafaraz.locateme.data.model.UpdateItemRequest
import com.mustafafaraz.locateme.utils.ImageHelper
import com.mustafafaraz.locateme.utils.TokenManager
import kotlinx.coroutines.launch

class EditItem : AppCompatActivity() {

    private lateinit var backButton: ImageView
    private lateinit var itemTypeSpinner: Spinner
    private lateinit var itemTitle: EditText
    private lateinit var itemCategory: Spinner
    private lateinit var itemDescription: EditText
    private lateinit var itemStatusSpinner: Spinner
    private lateinit var itemLocation: EditText
    private lateinit var locationLabel: TextView
    private lateinit var saveButton: Button
    private lateinit var deleteButton: Button
    private lateinit var photoCountText: TextView
    private lateinit var photosRecyclerView: RecyclerView
    private lateinit var addPhotoButton: Button
    private lateinit var progressBar: ProgressBar

    private lateinit var tokenManager: TokenManager
    private lateinit var photoAdapter: EditPhotoAdapter
    private val selectedPhotos = mutableListOf<Any>() // Can be Uri or String URL

    private var itemId: Int = -1
    private var currentItem: com.mustafafaraz.locateme.data.model.Item? = null

    // Photo picker launcher
    private val photoPickerLauncher = registerForActivityResult(
        ActivityResultContracts.GetMultipleContents()
    ) { uris ->
        if (uris.isNotEmpty()) {
            for (uri in uris) {
                if (selectedPhotos.size < 5) {
                    if (!selectedPhotos.contains(uri)) {
                        photoAdapter.addPhoto(uri)
                    }
                }
            }
            updatePhotoCount()
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_edit_item)

        tokenManager = TokenManager(this)

        // Get item ID from intent
        itemId = intent.getIntExtra("item_id", -1)

        if (itemId == -1) {
            Toast.makeText(this, "Invalid item", Toast.LENGTH_SHORT).show()
            finish()
            return
        }

        initializeViews()
        setupSpinners()
        setupPhotoRecyclerView()
        setupClickListeners()

        // Load item details from API
        loadItemDetails()
    }

    private fun initializeViews() {
        backButton = findViewById(R.id.back_button)
        itemTypeSpinner = findViewById(R.id.item_type_spinner)
        itemTitle = findViewById(R.id.item_title)
        itemCategory = findViewById(R.id.item_category)
        itemDescription = findViewById(R.id.item_description)
        itemStatusSpinner = findViewById(R.id.item_status_spinner)
        itemLocation = findViewById(R.id.item_location)
        locationLabel = findViewById(R.id.location_label)
        saveButton = findViewById(R.id.save_button)
        deleteButton = findViewById(R.id.delete_button)
        photoCountText = findViewById(R.id.photo_count_text)
        photosRecyclerView = findViewById(R.id.photos_recycler_view)
        addPhotoButton = findViewById(R.id.add_photo_button)
    }

    private fun setupSpinners() {
        // Item Type Spinner
        val itemTypes = arrayOf("LOST", "FOUND")
        val typeAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, itemTypes)
        typeAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemTypeSpinner.adapter = typeAdapter

        // Update location label when item type changes
        itemTypeSpinner.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onItemSelected(parent: AdapterView<*>?, view: View?, position: Int, id: Long) {
                updateLocationLabel(position)
            }

            override fun onNothingSelected(parent: AdapterView<*>?) {}
        }

        // Category Spinner
        val categories = arrayOf(
            "Select Category",
            "ELECTRONICS",
            "BAGS",
            "KEYS",
            "CLOTHING",
            "OTHER"
        )
        val categoryAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, categories)
        categoryAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemCategory.adapter = categoryAdapter

        // Status Spinner
        val statuses = arrayOf("ACTIVE", "RESOLVED", "EXPIRED")
        val statusAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, statuses)
        statusAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemStatusSpinner.adapter = statusAdapter
    }

    private fun setupPhotoRecyclerView() {
        photoAdapter = EditPhotoAdapter(selectedPhotos) { position ->
            photoAdapter.removePhoto(position)
            updatePhotoCount()
        }

        photosRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@EditItem, LinearLayoutManager.HORIZONTAL, false)
            adapter = photoAdapter
        }
    }

    private fun setupClickListeners() {
        backButton.setOnClickListener {
            finish()
        }

        saveButton.setOnClickListener {
            handleSaveChanges()
        }

        deleteButton.setOnClickListener {
            showDeleteConfirmation()
        }

        addPhotoButton.setOnClickListener {
            if (selectedPhotos.size < 5) {
                photoPickerLauncher.launch("image/*")
            } else {
                Toast.makeText(this, "Maximum 5 photos allowed", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun loadItemDetails() {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@EditItem, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.getItemById(authHeader, itemId)

                if (response.isSuccessful && response.body()?.success == true) {
                    currentItem = response.body()?.data
                    currentItem?.let { displayItemData(it) }
                } else {
                    Toast.makeText(this@EditItem, "Failed to load item details", Toast.LENGTH_SHORT).show()
                    Log.e("EditItem", "Error: ${response.code()} - ${response.message()}")
                }
            } catch (e: Exception) {
                Log.e("EditItem", "Error loading item", e)
                Toast.makeText(this@EditItem, "Network error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun displayItemData(item: com.mustafafaraz.locateme.data.model.Item) {
        // Set item type
        val typePosition = if (item.type == "LOST") 0 else 1
        itemTypeSpinner.setSelection(typePosition)

        // Set basic info
        itemTitle.setText(item.title)
        itemDescription.setText(item.description)
        itemLocation.setText(item.location)

        // Set category
        val categoryList = listOf("Select Category", "ELECTRONICS", "BAGS", "KEYS", "CLOTHING", "OTHER")
        val categoryPosition = categoryList.indexOf(item.category)
        if (categoryPosition >= 0) {
            itemCategory.setSelection(categoryPosition)
        }

        // Set status
        val statusList = listOf("ACTIVE", "RESOLVED", "EXPIRED")
        val statusPosition = statusList.indexOf(item.status)
        if (statusPosition >= 0) {
            itemStatusSpinner.setSelection(statusPosition)
        }

        // Load existing images
        selectedPhotos.clear()
        if (item.imageUrls.isNotEmpty()) {
            selectedPhotos.addAll(item.imageUrls)
            photoAdapter.notifyDataSetChanged()
            updatePhotoCount()
        }

        Log.d("EditItem", "Item loaded: ${item.title}, Images: ${item.imageUrls.size}")
    }

    private fun handleSaveChanges() {
        // Validate inputs
        val title = itemTitle.text.toString().trim()
        val description = itemDescription.text.toString().trim()
        val location = itemLocation.text.toString().trim()
        val type = itemTypeSpinner.selectedItem.toString()
        val category = itemCategory.selectedItem.toString()
        val status = itemStatusSpinner.selectedItem.toString()

        if (title.isEmpty() || description.isEmpty() || location.isEmpty()) {
            Toast.makeText(this, "Please fill all required fields", Toast.LENGTH_SHORT).show()
            return
        }

        if (category == "Select Category") {
            Toast.makeText(this, "Please select a category", Toast.LENGTH_SHORT).show()
            return
        }

        lifecycleScope.launch {
            try {
                saveButton.isEnabled = false
                saveButton.text = "Saving..."

                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@EditItem, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"

                // Process images: convert new URIs to base64, keep existing URLs as is
                val imageList = mutableListOf<String>()
                for (photo in selectedPhotos) {
                    when (photo) {
                        is Uri -> {
                            // New image - convert to base64
                            val base64 = ImageHelper.uriToBase64(this@EditItem, photo)
                            if (base64 != null) {
                                imageList.add(base64)
                            }
                        }
                        is String -> {
                            // Existing image URL - extract the path (remove server URL)
                            val path = photo.substringAfter("/uploads/")
                            if (path.isNotEmpty()) {
                                imageList.add("uploads/$path")
                            }
                        }
                    }
                }

                val updateRequest = UpdateItemRequest(
                    title = title,
                    description = description,
                    category = category,
                    location = location,
                    type = type,
                    status = status,
                    itemImages = if (imageList.isNotEmpty()) imageList else null
                )

                val response = RetrofitClient.apiService.updateItem(authHeader, itemId, updateRequest)

                saveButton.isEnabled = true
                saveButton.text = "Save Changes"

                if (response.isSuccessful && response.body()?.success == true) {
                    Toast.makeText(this@EditItem, "Item updated successfully", Toast.LENGTH_SHORT).show()
                    setResult(RESULT_OK)
                    finish()
                } else {
                    Toast.makeText(this@EditItem, "Failed to update item", Toast.LENGTH_SHORT).show()
                    Log.e("EditItem", "Error: ${response.code()} - ${response.errorBody()?.string()}")
                }
            } catch (e: Exception) {
                saveButton.isEnabled = true
                saveButton.text = "Save Changes"
                Log.e("EditItem", "Error updating item", e)
                Toast.makeText(this@EditItem, "Network error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun showDeleteConfirmation() {
        AlertDialog.Builder(this)
            .setTitle("Delete Item")
            .setMessage("Are you sure you want to delete this item? This action cannot be undone.")
            .setPositiveButton("Delete") { _, _ ->
                handleDeleteItem()
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun handleDeleteItem() {
        lifecycleScope.launch {
            try {
                deleteButton.isEnabled = false
                deleteButton.text = "Deleting..."

                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@EditItem, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.deleteItem(authHeader, itemId)

                deleteButton.isEnabled = true
                deleteButton.text = "Delete Item"

                if (response.isSuccessful && response.body()?.success == true) {
                    Toast.makeText(this@EditItem, "Item deleted successfully", Toast.LENGTH_SHORT).show()
                    setResult(RESULT_OK)
                    finish()
                } else {
                    Toast.makeText(this@EditItem, "Failed to delete item", Toast.LENGTH_SHORT).show()
                    Log.e("EditItem", "Error: ${response.code()} - ${response.message()}")
                }
            } catch (e: Exception) {
                deleteButton.isEnabled = true
                deleteButton.text = "Delete Item"
                Log.e("EditItem", "Error deleting item", e)
                Toast.makeText(this@EditItem, "Network error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun updateLocationLabel(typePosition: Int) {
        locationLabel.text = if (typePosition == 0) {
            "Where did you lose it? *"
        } else {
            "Where did you find it? *"
        }
    }

    private fun updatePhotoCount() {
        photoCountText.text = "${selectedPhotos.size}/5 Photos"
    }
}

package com.mustafafaraz.locateme

import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.ImageView
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.mustafafaraz.locateme.adapter.MyItemsAdapter
import com.mustafafaraz.locateme.data.api.RetrofitClient
import com.mustafafaraz.locateme.data.model.Item
import com.mustafafaraz.locateme.utils.TokenManager
import kotlinx.coroutines.launch

class MyItems : AppCompatActivity() {

    private lateinit var tabActive: TextView
    private lateinit var tabResolved: TextView
    private lateinit var tabExpired: TextView
    private lateinit var backButton: ImageView
    private lateinit var recyclerView: RecyclerView
    private lateinit var adapter: MyItemsAdapter
    private lateinit var progressBar: ProgressBar
    private lateinit var emptyView: TextView
    private lateinit var tokenManager: TokenManager

    private var currentTab = "ACTIVE" // Track current tab (uppercase to match backend)
    private lateinit var allItems: MutableList<Item>

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_my_items)

        tokenManager = TokenManager(this)

        initializeViews()
        setupRecyclerView()
        setupTabListeners()

        // Load items from API
        loadMyItems()
    }

    private fun initializeViews() {
        tabActive = findViewById(R.id.tab_active)
        tabResolved = findViewById(R.id.tab_resolved)
        tabExpired = findViewById(R.id.tab_expired)
        backButton = findViewById(R.id.back_button)
        recyclerView = findViewById(R.id.my_items_recyclerview)
        progressBar = findViewById(R.id.progress_bar)
        emptyView = findViewById(R.id.empty_view)

        backButton.setOnClickListener {
            finish()
        }

        // Initialize empty list
        allItems = mutableListOf()
    }

    private fun setupTabListeners() {
        tabActive.setOnClickListener {
            if (currentTab != "ACTIVE") {
                switchTab("ACTIVE")
            }
        }

        tabResolved.setOnClickListener {
            if (currentTab != "RESOLVED") {
                switchTab("RESOLVED")
            }
        }

        tabExpired.setOnClickListener {
            if (currentTab != "EXPIRED") {
                switchTab("EXPIRED")
            }
        }

        // Set active tab as default
        switchTab("ACTIVE")
    }

    private fun switchTab(tab: String) {
        currentTab = tab

        // Reset all tabs
        tabActive.background = null
        tabResolved.background = null
        tabExpired.background = null

        tabActive.setTextColor(ContextCompat.getColor(this, R.color.text_color))
        tabResolved.setTextColor(ContextCompat.getColor(this, R.color.text_color))
        tabExpired.setTextColor(ContextCompat.getColor(this, R.color.text_color))

        // Highlight selected tab
        when (tab) {
            "ACTIVE" -> {
                tabActive.setBackgroundResource(R.drawable.selected_button_login_signup)
                tabActive.setTextColor(ContextCompat.getColor(this, R.color.black))
            }
            "RESOLVED" -> {
                tabResolved.setBackgroundResource(R.drawable.selected_button_login_signup)
                tabResolved.setTextColor(ContextCompat.getColor(this, R.color.black))
            }
            "EXPIRED" -> {
                tabExpired.setBackgroundResource(R.drawable.selected_button_login_signup)
                tabExpired.setTextColor(ContextCompat.getColor(this, R.color.black))
            }
        }

        // Reload items with filter
        loadMyItems()
    }

    private fun loadMyItems() {
        lifecycleScope.launch {
            try {
                // Show loading
                progressBar.visibility = View.VISIBLE
                emptyView.visibility = View.GONE
                recyclerView.visibility = View.GONE

                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@MyItems, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"

                Log.d("MyItems", "Loading items with status: $currentTab")

                // Make API call with status filter
                val response = RetrofitClient.apiService.getMyItems(
                    token = authHeader,
                    status = currentTab
                )

                // Hide loading
                progressBar.visibility = View.GONE

                if (response.isSuccessful && response.body()?.success == true) {
                    val items = response.body()?.data ?: emptyList()

                    Log.d("MyItems", "Received ${items.size} items")

                    allItems.clear()
                    allItems.addAll(items)

                    if (items.isEmpty()) {
                        emptyView.visibility = View.VISIBLE
                        emptyView.text = "No ${currentTab.lowercase()} items"
                        recyclerView.visibility = View.GONE
                    } else {
                        emptyView.visibility = View.GONE
                        recyclerView.visibility = View.VISIBLE
                        adapter.updateItems(allItems)
                    }
                } else {
                    Toast.makeText(this@MyItems, "Failed to load items", Toast.LENGTH_SHORT).show()
                    emptyView.visibility = View.VISIBLE
                    emptyView.text = "Failed to load items"
                }
            } catch (e: Exception) {
                Log.e("MyItems", "Error loading items", e)
                progressBar.visibility = View.GONE
                emptyView.visibility = View.VISIBLE
                emptyView.text = "Error: ${e.message}"
                Toast.makeText(this@MyItems, "Network error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun setupRecyclerView() {
        recyclerView.layoutManager = LinearLayoutManager(this)
        adapter = MyItemsAdapter(this, allItems)
        recyclerView.adapter = adapter
    }
}

package com.mustafafaraz.locateme

import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.ImageView
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.mustafafaraz.locateme.adapter.MyItemsAdapter
import com.mustafafaraz.locateme.data.api.RetrofitClient
import com.mustafafaraz.locateme.data.model.Item
import com.mustafafaraz.locateme.utils.TokenManager
import kotlinx.coroutines.launch

class MyItems : AppCompatActivity() {

    private lateinit var tabActive: TextView
    private lateinit var tabResolved: TextView
    private lateinit var tabExpired: TextView
    private lateinit var backButton: ImageView
    private lateinit var recyclerView: RecyclerView
    private lateinit var adapter: MyItemsAdapter
    private lateinit var progressBar: ProgressBar
    private lateinit var emptyView: TextView
    private lateinit var tokenManager: TokenManager

    private var currentTab = "ACTIVE" // Track current tab (uppercase to match backend)
    private lateinit var allItems: MutableList<Item>

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_my_items)

        tokenManager = TokenManager(this)

        initializeViews()
        setupRecyclerView()
        setupTabListeners()

        // Load items from API
        loadMyItems()
    }

    private fun initializeViews() {
        tabActive = findViewById(R.id.tab_active)
        tabResolved = findViewById(R.id.tab_resolved)
        tabExpired = findViewById(R.id.tab_expired)
        backButton = findViewById(R.id.back_button)
        recyclerView = findViewById(R.id.my_items_recyclerview)
        progressBar = findViewById(R.id.progress_bar)
        emptyView = findViewById(R.id.empty_view)

        backButton.setOnClickListener {
            finish()
        }

        // Initialize empty list
        allItems = mutableListOf()
    }

    private fun setupTabListeners() {
        tabActive.setOnClickListener {
            if (currentTab != "ACTIVE") {
                switchTab("ACTIVE")
            }
        }

        tabResolved.setOnClickListener {
            if (currentTab != "RESOLVED") {
                switchTab("RESOLVED")
            }
        }

        tabExpired.setOnClickListener {
            if (currentTab != "EXPIRED") {
                switchTab("EXPIRED")
            }
        }

        // Set active tab as default
        switchTab("ACTIVE")
    }

    private fun switchTab(tab: String) {
        currentTab = tab

        // Reset all tabs
        tabActive.background = null
        tabResolved.background = null
        tabExpired.background = null

        tabActive.setTextColor(ContextCompat.getColor(this, R.color.black))
        tabResolved.setTextColor(ContextCompat.getColor(this, R.color.black))
        tabExpired.setTextColor(ContextCompat.getColor(this, R.color.black))

        // Highlight selected tab with circular background
        when (tab) {
            "ACTIVE" -> {
                tabActive.setBackgroundResource(R.drawable.selected_button_login_signup)
            }
            "RESOLVED" -> {
                tabResolved.setBackgroundResource(R.drawable.selected_button_login_signup)
            }
            "EXPIRED" -> {
                tabExpired.setBackgroundResource(R.drawable.selected_button_login_signup)
            }
        }

        // Reload items with filter
        loadMyItems()
    }

    private fun loadMyItems() {
        lifecycleScope.launch {
            try {
                // Show loading
                progressBar.visibility = View.VISIBLE
                emptyView.visibility = View.GONE
                recyclerView.visibility = View.GONE

                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@MyItems, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"

                Log.d("MyItems", "Loading items with status: $currentTab")

                // Make API call with status filter
                val response = RetrofitClient.apiService.getMyItems(
                    token = authHeader,
                    status = currentTab
                )

                // Hide loading
                progressBar.visibility = View.GONE

                if (response.isSuccessful && response.body()?.success == true) {
                    val items = response.body()?.data ?: emptyList()

                    Log.d("MyItems", "Received ${items.size} items")

                    allItems.clear()
                    allItems.addAll(items)

                    if (items.isEmpty()) {
                        emptyView.visibility = View.VISIBLE
                        emptyView.text = "No ${currentTab.lowercase()} items"
                        recyclerView.visibility = View.GONE
                    } else {
                        emptyView.visibility = View.GONE
                        recyclerView.visibility = View.VISIBLE
                        adapter.updateItems(allItems)
                    }
                } else {
                    Toast.makeText(this@MyItems, "Failed to load items", Toast.LENGTH_SHORT).show()
                    emptyView.visibility = View.VISIBLE
                    emptyView.text = "Failed to load items"
                }
            } catch (e: Exception) {
                Log.e("MyItems", "Error loading items", e)
                progressBar.visibility = View.GONE
                emptyView.visibility = View.VISIBLE
                emptyView.text = "Error: ${e.message}"
                Toast.makeText(this@MyItems, "Network error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun setupRecyclerView() {
        recyclerView.layoutManager = LinearLayoutManager(this)
        adapter = MyItemsAdapter(this, allItems)
        recyclerView.adapter = adapter
    }
}

package com.mustafafaraz.locateme

import android.os.Bundle
import android.view.View
import android.widget.ArrayAdapter
import android.widget.Button
import android.widget.EditText
import android.widget.ImageView
import android.widget.Spinner
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat

class ReportItem : AppCompatActivity() {

    private lateinit var toggleLost: TextView
    private lateinit var toggleFound: TextView
    private lateinit var locationLabel: TextView
    private lateinit var reportButton: Button

    private lateinit var itemTitle: EditText
    private lateinit var itemCategory: Spinner
    private lateinit var itemDescription: EditText
    private lateinit var itemLocation: Spinner
    private lateinit var contactMethod: EditText
    private lateinit var contactInfo: EditText

    private var isLostItem = true

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_report_item)

        initializeViews()
        setupToggleListeners()
        setupSpinners()
        setupClickListeners()
    }

    private fun initializeViews() {
        toggleLost = findViewById(R.id.toggle_lost)
        toggleFound = findViewById(R.id.toggle_found)
        locationLabel = findViewById(R.id.location_label)
        reportButton = findViewById(R.id.report_button)

        itemTitle = findViewById(R.id.item_title)
        itemCategory = findViewById(R.id.item_category)
        itemDescription = findViewById(R.id.item_description)
        itemLocation = findViewById(R.id.item_location)
        contactMethod = findViewById(R.id.contact_method)
        contactInfo = findViewById(R.id.contact_info)
    }

    private fun setupToggleListeners() {
        toggleLost.setOnClickListener {
            if (!isLostItem) {
                switchToLost()
            }
        }

        toggleFound.setOnClickListener {
            if (isLostItem) {
                switchToFound()
            }
        }
    }

    private fun setupSpinners() {
        // Category Spinner
        val categories = arrayOf(
            "Select Category",
            "Electronics",
            "Bags",
            "Keys",
            "Clothing",
            "Books",
            "Accessories",
            "Other"
        )
        val categoryAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, categories)
        categoryAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemCategory.adapter = categoryAdapter

        // Location Spinner
        val locations = arrayOf(
            "Select Location",
            "Library - 1st floor",
            "Library - 2nd floor",
            "Library - 3rd floor",
            "Cafeteria",
            "Main Building",
            "Lab Block",
            "Sports Complex",
            "Parking Area",
            "Other"
        )
        val locationAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, locations)
        locationAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemLocation.adapter = locationAdapter
    }

    private fun setupClickListeners() {
        // Back button
        findViewById<ImageView>(R.id.back_button).setOnClickListener {
            finish()
        }

        // Report button
        reportButton.setOnClickListener {
            handleReportSubmit()
        }

        // Add photo button
        findViewById<View>(R.id.add_photo_button).setOnClickListener {
            // TODO: Implement photo picker
        }

        // Bottom navigation
        findViewById<View>(R.id.nav_search).setOnClickListener {
            // TODO: Navigate to search/home
        }

        findViewById<View>(R.id.nav_report).setOnClickListener {
            // Already on report screen
        }

        findViewById<View>(R.id.nav_profile).setOnClickListener {
            // TODO: Navigate to profile
        }
    }

    private fun switchToLost() {
        isLostItem = true

        // Update toggle buttons
        toggleLost.setBackgroundResource(R.drawable.selected_button_login_signup)
        toggleLost.setTextColor(ContextCompat.getColor(this, R.color.black))

        toggleFound.background = null
        toggleFound.setTextColor(ContextCompat.getColor(this, R.color.black))

        // Update text labels
        locationLabel.text = "Where did you lose it? *"
        reportButton.text = "Report Lost Item"
    }

    private fun switchToFound() {
        isLostItem = false

        // Update toggle buttons
        toggleLost.background = null
        toggleLost.setTextColor(ContextCompat.getColor(this, R.color.black))

        toggleFound.setBackgroundResource(R.drawable.selected_button_login_signup)
        toggleFound.setTextColor(ContextCompat.getColor(this, R.color.black))

        // Update text labels
        locationLabel.text = "Where did you find it? *"
        reportButton.text = "Report Found Item"
    }

    private fun handleReportSubmit() {
        val title = itemTitle.text.toString()
        val category = itemCategory.selectedItem.toString()
        val description = itemDescription.text.toString()
        val location = itemLocation.selectedItem.toString()
        val method = contactMethod.text.toString()
        val contact = contactInfo.text.toString()

        // Validation
        if (title.isEmpty()) {
            itemTitle.error = "Please enter item title"
            return
        }

        if (category == "Select Category") {
            // Show error for category
            return
        }

        if (description.isEmpty()) {
            itemDescription.error = "Please enter description"
            return
        }

        if (location == "Select Location") {
            // Show error for location
            return
        }

        if (method.isEmpty()) {
            contactMethod.error = "Please enter contact method"
            return
        }

        if (contact.isEmpty()) {
            contactInfo.error = "Please enter contact information"
            return
        }

        // TODO: Submit the report to backend/database
        val itemType = if (isLostItem) "Lost" else "Found"

        // For now, just finish the activity
        finish()
    }
}

package com.mustafafaraz.locateme.adapter

import android.net.Uri
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.ImageView
import androidx.recyclerview.widget.RecyclerView
import com.bumptech.glide.Glide
import com.mustafafaraz.locateme.R

class EditPhotoAdapter(
    private val photos: MutableList<Any>, // Can be Uri or String URL
    private val onRemoveClick: (Int) -> Unit
) : RecyclerView.Adapter<EditPhotoAdapter.PhotoViewHolder>() {

    inner class PhotoViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val imageView: ImageView = itemView.findViewById(R.id.photo_image)
        val removeButton: ImageView = itemView.findViewById(R.id.remove_photo)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): PhotoViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_photo, parent, false)
        return PhotoViewHolder(view)
    }

    override fun onBindViewHolder(holder: PhotoViewHolder, position: Int) {
        val photo = photos[position]

        // Load image from URI or URL
        when (photo) {
            is Uri -> {
                holder.imageView.setImageURI(photo)
            }
            is String -> {
                Glide.with(holder.itemView.context)
                    .load(photo)
                    .placeholder(R.drawable.item_placeholder)
                    .error(R.drawable.item_placeholder)
                    .centerCrop()
                    .into(holder.imageView)
            }
        }

        // Remove button click
        holder.removeButton.setOnClickListener {
            onRemoveClick(position)
        }
    }

    override fun getItemCount(): Int = photos.size

    fun addPhoto(item: Any) {
        if (photos.size < 5) {
            photos.add(item)
            notifyItemInserted(photos.size - 1)
        }
    }

    fun removePhoto(position: Int) {
        if (position < photos.size) {
            photos.removeAt(position)
            notifyItemRemoved(position)
            notifyItemRangeChanged(position, photos.size)
        }
    }

    fun getPhotos(): List<Any> = photos
}

package com.mustafafaraz.locateme.data.api

import com.mustafafaraz.locateme.data.model.*
import retrofit2.Response
import retrofit2.http.*

interface ApiService {

    // Authentication Endpoints
    @POST("api/auth/signup")
    suspend fun signup(@Body request: SignupRequest): Response<ApiResponse<AuthResponse>>

    @POST("api/auth/login")
    suspend fun login(@Body request: LoginRequest): Response<ApiResponse<AuthResponse>>

    // User Profile Endpoints
    @GET("api/users/profile")
    suspend fun getProfile(
        @Header("Authorization") token: String
    ): Response<ApiResponse<User>>

    // Item Endpoints
    @POST("api/items")
    suspend fun createItem(
        @Header("Authorization") token: String,
        @Body request: CreateItemRequest
    ): Response<ApiResponse<Item>>

    @GET("api/items")
    suspend fun getItems(
        @Header("Authorization") token: String,
        @Query("type") type: String? = null,
        @Query("category") category: String? = null,
        @Query("search") search: String? = null
    ): Response<ApiResponse<List<Item>>>

    @GET("api/items/{id}")
    suspend fun getItemById(
        @Header("Authorization") token: String,
        @Path("id") itemId: Int
    ): Response<ApiResponse<Item>>

    @GET("api/items/my-items")
    suspend fun getMyItems(
        @Header("Authorization") token: String,
        @Query("type") type: String? = null,
        @Query("status") status: String? = null
    ): Response<ApiResponse<List<Item>>>
}

